26	
27	    // Draft is the user-facing, locally mutable copy. The React Query cache stays as server truth;
28	    // staged edits (adding steps, etc.) live here until the user publishes. Seeded once when the
29	    // automation first loads, and reset to the response after every successful edit.
30	    const [draft, setDraft] = React.useState<AutomationDetail | undefined>(undefined);
31	    React.useEffect(() => {
32	        if (automation) {
33	            setDraft((oldDraft) => {
34	                return oldDraft?.id === automation.id ? oldDraft : automation;
35	            });
36	        }
37	    }, [automation]);
38	
39	    // Only compare the fields the user can edit; server-stamped fields like `updated_at` would
40	    // otherwise flip the dirty flag immediately after every successful publish.
41	    const hasUnsavedChanges = !!draft
42	        && !!automation
43	        && !dequal(editableSlice(draft), editableSlice(automation));
44	
45	    const onDraftChange = (next: AutomationDetail) => {
46	        setDraft(next);
47	        setEditState((prev) => {
48	            if (prev === 'failed to save' || prev === 'failed to publish' || prev === 'failed to unpublish') {
49	                return 'idle';
50	            }
51	            return prev;
52	        });
53	    };
54	
55	    const save = (statusToSave?: AutomationStatus) => {
56	        if (!draft) {
57	            throw new Error('Cannot edit an automation that has not loaded.');
58	        }
59	
60	        let errorState: AutomationEditState;
61	        switch (statusToSave) {
62	        case undefined:
63	            setEditState('saving');
64	            errorState = 'failed to save';
65	            break;
66	        case 'active':
67	            setEditState('publishing');
68	            errorState = 'failed to publish';
69	            break;
70	        case 'inactive':
71	            setEditState('unpublishing');
72	            errorState = 'failed to unpublish';
73	            break;
74	        default: {
